{
  "summary": "Instrument cluster/panel: dashboard froze and truck would not restart, recurred while traveling with warning lights/sound; flagged unsafe and unresolved after service.",
  "group": "instrumentation",
  "symptoms": [
    "dashboard frozen",
    "truck would not restart",
    "no warning light displayed at first",
    "warning lights and sound went off"
  ],
  "conditions": [
    "intermittent",
    "after service"
  ],
  "fault_codes": [],
  "safety_relevant": true,
  "missing_info": [
    "mileage",
    "date"
  ],
  "clues": [
    {
      "kind": "component_group",
      "quote": "ELECTRICAL SYSTEM: INSTRUMENT CLUSTER/PANEL"
    },
    {
      "kind": "symptom",
      "quote": "the trucks dashboard was frozen"
    },
    {
      "kind": "symptom",
      "quote": "the truck would not restart"
    },
    {
      "kind": "symptom",
      "quote": "No warning light displayed at this time and the truck was stationary."
    },
    {
      "kind": "condition",
      "quote": "Dash froze again while the truck was traveling"
    },
    {
      "kind": "symptom",
      "quote": "warning lights and sound went off this time"
    },
    {
      "kind": "safety",
      "quote": "No Accident occurred but having the dashboard fail when in motions was a very unsafe situation"
    },
    {
      "kind": "safety",
      "quote": "if the trucks dash system was to freeze up when the crane is deployed that would also be an unsafe situation"
    },
    {
      "kind": "condition",
      "quote": "The truck is currently at a Peterbilt Service provider, but the issue has not been resolved after 5 weeks."
    }
  ]
}

